const int LED = 2;
void setup() {
  pinMode(LED, OUTPUT);
  Serial.begin(115200);
  Serial.println("CircuitForge ESP · Blink");
}
void loop() {
  digitalWrite(LED, HIGH);
  Serial.println("LED ON");
  delay(20);
  digitalWrite(LED, LOW);
  Serial.println("LED OFF");
  delay(20);
}

