esp32c3:counter.source:
struct Counter {
  unsigned value;
  Counter() : value(37) {}
};
Counter count;
volatile byte memory[2048];
void setup() {
  Serial.begin(115200);
  memory[0] = 37;
  memory[2047] = 77;
}
void loop() {
  Serial.print("COUNT=");
  Serial.print(count.value++);
  Serial.print(" RAM=");
  Serial.print((unsigned)memory[0]);
  Serial.print("/");
  Serial.print((unsigned)memory[2047]);
  Serial.print(" ms=");
  Serial.println(millis());
  delay(20);
}

