#pragma once
#include "Arduino.h"
class Blinker {
  byte pin;
  bool high = false;
public:
  Blinker(byte p) : pin(p) {}
  void begin();
  void tick();
};

#include "blinker.hpp"
void Blinker::begin() { pinMode(pin, OUTPUT); }
void Blinker::tick() {
  high = !high;
  digitalWrite(pin, high);
  Serial.println(high ? "MULTI HIGH" : "MULTI LOW");
}

